{
  "name": "BioTek Cytation微孔板成像读板仪",
  "name_en": "BioTek Cytation Plate Reader Imager",
  "manufacturer": "Agilent BioTek",
  "description": "Cytation是一类带显微成像功能的微孔板读板仪，可对多孔板样品进行自动对焦、位移扫描、明场或滤光片成像，并支持相机曝光、增益、物镜和照明设置。它常用于细胞培养板成像、荧光/明场观察以及自动化板式实验的数据采集。",
  "description_en": "The Cytation is a microplate reader with integrated microscopy-style imaging. It can autofocus, move across wells, perform brightfield or filtered imaging, and control camera exposure, gain, objectives, and illumination. It is commonly used for imaging cell culture plates, fluorescence or brightfield observation, and automated data collection in plate-based assays.",
  "actions": [
    {
      "action_name": "auto-supports_heating",
      "description": "查询设备是否支持加热。",
      "description_en": "Query whether the device supports heating."
    },
    {
      "action_name": "auto-supports_cooling",
      "description": "查询设备是否支持冷却。",
      "description_en": "Query whether the device supports cooling."
    },
    {
      "action_name": "auto-objectives",
      "description": "获取可用物镜列表。",
      "description_en": "Get the list of available objectives."
    },
    {
      "action_name": "auto-filters",
      "description": "获取可用滤光片列表。",
      "description_en": "Get the list of available filters."
    },
    {
      "action_name": "auto-start_acquisition",
      "description": "开始相机采集。",
      "description_en": "Start camera acquisition."
    },
    {
      "action_name": "auto-stop_acquisition",
      "description": "停止相机采集。",
      "description_en": "Stop camera acquisition."
    },
    {
      "action_name": "auto-led_on",
      "description": "打开LED照明并设置强度。",
      "description_en": "Turn on the LED illumination and set its intensity."
    },
    {
      "action_name": "auto-led_off",
      "description": "关闭LED照明。",
      "description_en": "Turn off the LED illumination."
    },
    {
      "action_name": "auto-set_focus",
      "description": "设置焦点位置。",
      "description_en": "Set the focus position."
    },
    {
      "action_name": "auto-set_position",
      "description": "设置视野在孔内的X/Y位置。",
      "description_en": "Set the X/Y field position within the selected well."
    },
    {
      "action_name": "auto-set_auto_exposure",
      "description": "设置是否使用自动曝光。",
      "description_en": "Set whether auto exposure is used."
    },
    {
      "action_name": "auto-set_exposure",
      "description": "设置曝光时间。",
      "description_en": "Set the exposure time."
    },
    {
      "action_name": "auto-select",
      "description": "选择微孔板中的目标孔位。",
      "description_en": "Select the target well in the microplate."
    },
    {
      "action_name": "auto-set_gain",
      "description": "设置相机增益。",
      "description_en": "Set the camera gain."
    },
    {
      "action_name": "auto-set_objective",
      "description": "设置成像物镜。",
      "description_en": "Set the imaging objective."
    },
    {
      "action_name": "auto-set_imaging_mode",
      "description": "设置成像模式和LED强度。",
      "description_en": "Set the imaging mode and LED intensity."
    },
    {
      "action_name": "auto-capture",
      "description": "在指定孔位和成像参数下采集图像。",
      "description_en": "Capture image data using the specified well and imaging parameters."
    }
  ],
  "tag_hints": [
    "microplate imaging",
    "plate reader",
    "cell imaging",
    "brightfield imaging",
    "fluorescence imaging",
    "objective switching",
    "autofocus",
    "well-plate assays"
  ]
}

